with lines as (select id, coupon_codes, attr_key, v from carts lateral view explode(attributes) x as attr_key, v), flattened as (select id, attr_key, v, explode_outer(coupon_codes) as code from lines), cleaned as (select *, concat_ws(',', code, attr_key) as code_attr_key_key from flattened where code = 'BUNDLE'), filtered as (select id, attr_key, v, code_attr_key_key, lower(attr_key) as attr_key_lower, concat_ws('-', attr_key, code) as attr_key_code_key, coalesce(attr_key, 'DIRECT') as attr_key_filled from cleaned where code = 'WELCOME5'), matched_keys as (select id from filtered intersect select id from carts where customer_id is not null), kept_rows as (select s.* from filtered s join matched_keys k on s.id = k.id) select id, attr_key, v, code_attr_key_key, attr_key_lower, attr_key_code_key, attr_key_filled, case when attr_key rlike '^(device|gift)$' then 'EXTENDED' else 'PRIORITY' end as attr_key_zone from kept_rows;
